// 原道路/泥地成本与丘陵射程是一张固定表；未知兵种/地形失败，不回退为平地。
#include "military_field_terrain.hpp"
#include "resident/model/common_model.hpp"
#include "military_commander.hpp"
#include "military_rout_orders.hpp"
#include <algorithm>
#include <set>
namespace hanmo::resident {
Status validate_military_field_terrain_rule(const MilitaryFieldTerrainRule& rule){return rule.profile=="terrain_and_zones_05_v1"?common_success():common_failure("UnknownMilitaryFieldTerrainRule",rule.profile);}
Outcome<StableId> select_military_field_contact_battlefield(const MilitaryFieldTerrainPolicy& policy,const StableId& approach){auto valid=validate_military_field_terrain_rule(policy.rule);if(!valid.ok)return {false,{},valid.error};if(approach.empty()||policy.battlefields.empty()||policy.battlefields.size()>32)return {false,{},common_failure("MilitaryFieldTerrainSelectionMismatch").error};std::set<StableId> sources,targets;StableId chosen=approach;for(const auto& binding:policy.battlefields){if(binding.approach_battlefield_id.empty()||binding.field_battlefield_id.empty()||binding.approach_battlefield_id==binding.field_battlefield_id||!sources.insert(binding.approach_battlefield_id).second||!targets.insert(binding.field_battlefield_id).second)return {false,{},common_failure("MilitaryFieldTerrainSelectionMismatch").error};if(binding.approach_battlefield_id==approach)chosen=binding.field_battlefield_id;}for(const auto& id:sources)if(targets.count(id))return {false,{},common_failure("MilitaryFieldTerrainRecursiveMapping",id).error};return {true,std::move(chosen),{}};}
Outcome<Integer> military_field_terrain_cost(const MilitaryFieldTerrainRule& rule,const StableId& category,const StableId& terrain){auto valid=validate_military_field_terrain_rule(rule);if(!valid.ok)return {false,{},valid.error};if(category!="infantry"&&category!="archer"&&category!="cavalry")return {false,{},common_failure("MilitaryFieldTroopCategoryRequired",category).error};Integer cost=-1;if(terrain=="plain"||terrain=="road")cost=1;else if(terrain=="forest")cost=category=="infantry"?1:category=="archer"?2:3;else if(terrain=="hill")cost=2;else if(terrain=="mud")cost=category=="cavalry"?4:2;else if(terrain!="water"&&terrain!="wall")return {false,{},common_failure("UnknownMilitaryFieldTerrain",terrain).error};return {true,cost,{}};}
Status validate_military_field_terrain_troop(const MilitaryFieldTerrainRule& rule,const TroopDefinition& troop){auto valid=validate_military_field_terrain_rule(rule);if(!valid.ok)return valid;const bool archer=troop.category=="archer",cavalry=troop.category=="cavalry";if(!archer&&!cavalry&&troop.category!="infantry")return common_failure("MilitaryFieldTroopCategoryRequired",troop.id);if(troop.movement!=(archer?2:cavalry?5:3)||troop.minimum_range!=(archer?2:1)||troop.maximum_range!=(archer?4:1))return common_failure("MilitaryFieldTroopRangeMismatch",troop.id);for(const auto* terrain:{"plain","road","forest","hill","mud","water","wall"}){auto cost=military_field_terrain_cost(rule,troop.category,terrain);if(!cost.ok)return {false,{},cost.error};auto it=troop.movement_costs.find(terrain);if(it==troop.movement_costs.end()||it->second!=std::max<Integer>(0,cost.value))return common_failure("MilitaryFieldTroopCostMismatch",troop.id+"/"+terrain);}return common_success();}
Status validate_military_field_terrain_policy(const MilitaryBattleCatalog& catalog){bool selected=false;for(const auto& board:catalog.battlefields)if(board.field_terrain){selected=true;auto valid=validate_military_field_terrain_rule(*board.field_terrain);if(!valid.ok)return valid;if(!board.rout_retreat||!catalog.sequential_round_rule||!catalog.commanded_damage_rule)return common_failure("MilitaryFieldTerrainPrerequisiteRequired",board.id);}return selected!=catalog.field_terrain_enabled?common_failure("MilitaryFieldTerrainSelectionMismatch"):common_success();}
Integer military_field_attack_maximum_range(const BattlefieldDefinition& board,const TroopDefinition& troop,HexPoint from){const auto* cell=military_hex::cell(board,from);return board.field_terrain&&troop.category=="archer"&&cell&&cell->terrain=="hill"?std::min<Integer>(5,troop.maximum_range+1):troop.maximum_range;}
// 仅敌方仍可指挥且未溃退部队施加控制区；本人佯退沿原已学战法解除该限制。
bool military_field_retreat_required(const MilitaryBattleRecord& battle,const MilitaryBattleCatalog& catalog,const StableId& id,const StableId& kind){if(kind=="feint")return false;const BattlefieldDefinition* board=nullptr;for(const auto& b:catalog.battlefields)if(b.id==battle.battlefield_id)board=&b;if(!board||!board->field_terrain)return false;const BattleUnit* subject=nullptr;for(const auto& u:battle.units)if(u.unit_id==id)subject=&u;if(!subject)return false;for(const auto& enemy:battle.units)if(enemy.side!=subject->side&&!enemy.withdrawn&&!enemy.fit.empty()&&enemy.morale>0&&military_commander_loss(enemy)!=2&&!military_unit_routing(enemy)&&military_hex::distance(enemy.position,subject->position)==1)return true;return false;}
}
